import { useEffect, useMemo, useRef, useState } from "react";
import { ActivityIndicator, Animated, Platform, Pressable, ScrollView, Text, View } from "react-native";
import { useLocalSearchParams, router } from "expo-router";
import { ScreenContainer } from "@/components/screen-container";
import { trpc } from "@/lib/trpc";
import { useColors } from "@/hooks/use-colors";
import type { ActionEnvelope, GameState, LegalAction, TileCode } from "@/shared/mahjong-types";
import { arenaTokens } from "@/constants/arena-tokens";
import { ArenaFeedback } from "@/components/arena-feedback";
import { ArenaSkeleton } from "@/components/arena-skeleton";
import { ArenaMetric } from "@/components/arena-metric";
import { ArenaCard } from "@/components/arena-ui";
import { recentMatchEvents } from "@/shared/action-history";
import { haptic } from "@/lib/haptics";
import { useAccessibilityPreferences } from "@/lib/accessibility-preferences";
import { useI18n } from "@/lib/i18n";
import { coachingModeDescription, coachingModeLabel, normalizeCoachingMode, type CoachingMode } from "@/shared/coaching-mode";
import { safeGetItem } from "@/shared/storage-utils";
import { getMultiTileChoices } from "@/lib/multi-tile-actions";
import { safeRemoveItem } from "@/shared/storage-utils";
import { safeSetItem } from "@/shared/storage-utils";
import { buildScoreBreakdown } from "@/shared/score-breakdown";
import { availableActionSummary, describeActionIntent, describeRoundTransition, describeTurnStatus, explainGameplayError } from "@/shared/gameplay-feedback";
import { describeGameplaySync } from "@/shared/gameplay-sync";
import * as Network from "expo-network";
import { useReducedMotion } from "@/hooks/use-reduced-motion";
import { appendActionLifecycle, createActionLifecycleEntry, formatActionLifecycleTime, type ActionLifecycleEntry } from "@/shared/action-lifecycle";
import { buildDiscardRiver, claimWindowLabel, claimWindowState, seatAccent, type DiscardRiverEntry } from "@/shared/discard-river";
import { tileAccessibilityLabel, tileSuitLabel } from "@/shared/mahjong-labels";

const ACTION_FILTER_OPTIONS = ["all", "pending", "confirmed", "rejected", "discard", "riichi", "chi", "pon", "kan", "tsumo", "ron", "pass", "seat0", "seat1", "seat2", "seat3"] as const;
type ActionFilter = typeof ACTION_FILTER_OPTIONS[number];

function stateKey(state: GameState | undefined): string {
  if (!state) return "empty";
  return `${state.phase}:${state.currentSeat}:${state.turn}:${state.handNumber}:${state.wall.length}`;
}

function Tile({ code, selected, legal, hapticsEnabled, disabled, language, onPress }: { code: TileCode; selected?: boolean; legal?: boolean; hapticsEnabled: boolean; disabled?: boolean; language: import("@/lib/i18n").LanguageCode; onPress?: () => void }) {
  return (
    <Pressable onPress={() => { if (hapticsEnabled) haptic.selection(); onPress?.(); }} disabled={disabled} hitSlop={6} accessibilityRole="button" accessibilityLabel={tileAccessibilityLabel(code, language, selected, legal)} accessibilityHint={language === "zh-Hans" ? (selected ? "已选为打牌候选" : legal ? "选择这张合法打牌候选牌" : "这张牌不在当前后端批准的打牌动作中") : language === "zh-Hant" ? (selected ? "已選為打牌候選" : legal ? "選擇這張合法打牌候選牌" : "這張牌不在目前後端核准的打牌動作中") : selected ? "Selected as the discard candidate" : legal ? "Select this legal discard candidate" : "This tile is not listed for the current backend-approved discard action"} accessibilityState={{ selected, disabled }} style={({ pressed }) => ({ minWidth: 48, minHeight: 82, alignItems: "center", justifyContent: "center", opacity: disabled ? 0.35 : pressed ? 0.72 : 1, transform: [{ translateY: selected ? -8 : 0 }, { scale: pressed ? 0.96 : 1 }] })}>
        <View className={`h-[70px] w-11 items-center justify-center rounded-lg border-2 bg-[#F7F0E3] ${selected ? "border-[3px] border-[#B87843] bg-[#FFF0D5]" : legal ? "border-[#2E6A59]" : "border-[#D7C8B2]"}`} style={selected ? { shadowColor: "#D7AA58", shadowOpacity: 0.65, shadowRadius: 8, shadowOffset: { width: 0, height: 3 }, elevation: 5 } : undefined}>
        <Text className="text-base font-bold text-[#17211F]">{code.slice(1)}</Text>
        <Text className="text-[10px] uppercase text-[#7B6B5A]">{tileSuitLabel(code[0] ?? "", language)}</Text>
      </View>
    </Pressable>
  );
}

export default function MatchScreen() {
  const { id } = useLocalSearchParams<{ id: string }>();
  const colors = useColors();
  const { hapticsEnabled, confirmBeforeDiscard } = useAccessibilityPreferences();
  const { language, t } = useI18n();
  const [selectedTile, setSelectedTile] = useState<string | undefined>();
  const [showCopilot, setShowCopilot] = useState(false);
  const [coachingMode, setCoachingMode] = useState<CoachingMode>("balanced");
  const [selectedComparisonMode, setSelectedComparisonMode] = useState<CoachingMode | null>(null);
  const [actionFeedback, setActionFeedback] = useState<string | null>(null);
  const [showAudit, setShowAudit] = useState(false);
  const [pendingClaim, setPendingClaim] = useState<LegalAction | null>(null);
  const [pendingDiscardAction, setPendingDiscardAction] = useState<LegalAction | null>(null);
  const [meldSuccessVisible, setMeldSuccessVisible] = useState(false);
  useEffect(() => { void safeGetItem("mahjong.sensei.coachingMode").then((value) => setCoachingMode(normalizeCoachingMode(value))); }, []);
  const [selectedClaimTiles, setSelectedClaimTiles] = useState<string[]>([]);
  const [optimisticAction, setOptimisticAction] = useState<ActionEnvelope["type"] | null>(null);
  const [retryAction, setRetryAction] = useState<ActionEnvelope | null>(null);
  const [actionTimeline, setActionTimeline] = useState<ActionLifecycleEntry[]>([]);
  const [selectedDiscard, setSelectedDiscard] = useState<DiscardRiverEntry | null>(null);
  const [claimToastVisible, setClaimToastVisible] = useState(false);
  const [actionFilter, setActionFilter] = useState<ActionFilter>("all");
  const [challengeOffset, setChallengeOffset] = useState(0);
  const lastActionRef = useRef<ActionEnvelope | null>(null);
  const nativeNetworkState = Network.useNetworkState();
  const [networkStatus, setNetworkStatus] = useState<"online" | "offline" | "unknown">(Platform.OS === "web" && typeof window !== "undefined" && window.navigator.onLine === false ? "offline" : Platform.OS === "web" ? "online" : "unknown");
  const reducedMotion = useReducedMotion();
  const transitionOpacity = useState(() => new Animated.Value(1))[0];
  const claimToastOpacity = useState(() => new Animated.Value(0))[0];
  const meldSuccessOpacity = useState(() => new Animated.Value(0))[0];
  const previousNetworkStatus = useRef(networkStatus);
  const previousClaimState = useRef<"open" | "closed" | "idle">("idle");
  const completionFeedbackSent = useRef(false);
  const previousTransitionKey = useRef<string | null>(null);
  const match = trpc.mahjong.get.useQuery({ id: String(id) }, { enabled: Boolean(id), refetchInterval: 1500 });
  const legal = trpc.mahjong.legalActions.useQuery({ id: String(id), seat: 0 }, { enabled: Boolean(id), refetchInterval: 1500 });
  const legalityPreview = trpc.mahjong.legalityPreview.useQuery({ id: String(id), seat: 0 }, { enabled: Boolean(id), refetchInterval: 2500 });
  const scorePreview = trpc.mahjong.scorePreview.useQuery({ id: String(id), seat: 0, tsumo: false, riichi: false, doraCount: 0 }, { enabled: Boolean(id), refetchInterval: 3000 });
  const audit = trpc.mahjong.audit.useQuery({ id: String(id) }, { enabled: Boolean(id), refetchInterval: 1500 });
  const aiMatchReport = trpc.mahjong.aiMatchReport.useQuery({ id: String(id) }, { enabled: Boolean(id), refetchInterval: 3000 });
  const analysis = trpc.mahjong.analyze.useMutation();
  const modeComparison = trpc.mahjong.compareCoachingModes.useMutation();
  const advanceRound = trpc.mahjong.advanceRound.useMutation({ onSuccess: (transition) => { setOptimisticAction(null); setActionFeedback(describeRoundTransition(transition.reason)); void match.refetch(); void legal.refetch(); void audit.refetch(); void aiMatchReport.refetch(); }, onError: (error) => { setOptimisticAction(null); setActionFeedback(explainGameplayError(error.message)); } });
  const submit = trpc.mahjong.submitAction.useMutation({ onSuccess: () => { const acceptedAction = lastActionRef.current; setPendingDiscardAction(null); setSelectedTile(undefined); setOptimisticAction(null); setRetryAction(null); if (lastActionRef.current) setActionTimeline((current) => appendActionLifecycle(current, createActionLifecycleEntry(lastActionRef.current as ActionEnvelope, "confirmed", undefined, language))); setActionFeedback("Action accepted. The table state and legal actions are refreshing."); if (["chi", "pon", "kan"].includes(acceptedAction?.type ?? "")) setMeldSuccessVisible(true); if (hapticsEnabled) haptic.success(); void match.refetch(); void legal.refetch(); void audit.refetch(); }, onError: (error) => { setOptimisticAction(null); setRetryAction(lastActionRef.current); if (lastActionRef.current) setActionTimeline((current) => appendActionLifecycle(current, createActionLifecycleEntry(lastActionRef.current as ActionEnvelope, "rejected", undefined, language))); setActionFeedback(explainGameplayError(error.message)); if (hapticsEnabled) haptic.error(); } });
  useEffect(() => {
    if (Platform.OS === "web") return;
    if (nativeNetworkState.isInternetReachable === false || nativeNetworkState.isConnected === false) setNetworkStatus("offline");
    else if (nativeNetworkState.isInternetReachable === true || nativeNetworkState.isConnected === true) setNetworkStatus("online");
    else setNetworkStatus("unknown");
  }, [nativeNetworkState.isConnected, nativeNetworkState.isInternetReachable]);
  useEffect(() => {
    if (Platform.OS !== "web" || typeof window === "undefined") return;
    const update = () => setNetworkStatus(window.navigator.onLine === false ? "offline" : "online");
    update();
    window.addEventListener("online", update);
    window.addEventListener("offline", update);
    return () => { window.removeEventListener("online", update); window.removeEventListener("offline", update); };
  }, []);
  useEffect(() => {
    if (previousNetworkStatus.current === "offline" && networkStatus === "online") {
      setActionFeedback("Connection restored. Refreshing the confirmed table state before actions resume.");
      void match.refetch();
      void legal.refetch();
      void audit.refetch();
      void aiMatchReport.refetch();
    }
    previousNetworkStatus.current = networkStatus;
  }, [aiMatchReport, audit, legal, match, networkStatus]);
  const transitionKey = stateKey(match.data);
  useEffect(() => {
    const previousKey = previousTransitionKey.current;
    if (previousKey && previousKey !== transitionKey && (pendingClaim || pendingDiscardAction)) {
      setPendingClaim(null);
      setPendingDiscardAction(null);
      setSelectedClaimTiles([]);
      setActionFeedback("The table changed before the claim was confirmed. Choose a fresh legal action from the updated state.");
    }
    previousTransitionKey.current = transitionKey;
  }, [pendingClaim, pendingDiscardAction, transitionKey]);
  useEffect(() => {
    if (reducedMotion) { transitionOpacity.setValue(1); return; }
    transitionOpacity.setValue(0.94);
    Animated.timing(transitionOpacity, { toValue: 1, duration: 220, useNativeDriver: true }).start();
  }, [reducedMotion, transitionKey, transitionOpacity]);
  const state = match.data;
  const player = state?.players[0];
  const activeComparison = modeComparison.data?.find((candidate) => candidate.recommendationId.endsWith(`-${selectedComparisonMode ?? coachingMode}`));
  const recommended = activeComparison?.alternatives?.[0] ?? analysis.data?.alternatives?.[0];
  const selectedTileData = player?.hand.find((tile) => tile.id === selectedTile);
  const tileCodes = useMemo(() => player?.hand.map((tile) => tile.code) ?? [], [player?.hand]);
  const historyItems = useMemo(() => recentMatchEvents(audit.data?.events ?? [], 6, audit.data?.snapshots ?? []), [audit.data?.events, audit.data?.snapshots]);
  const isYourTurn = state?.currentSeat === 0;
  const legalActions = legal.data ?? [];
  const enabledLegalActionCount = legalActions.filter((action) => action.enabled).length;
  const discardAction = legalActions.find((action) => action.type === "discard");
  const tileIsLegalForDiscard = (tile: { id: string; code: TileCode }) => Boolean(discardAction?.enabled && (!discardAction.tileIds?.length || discardAction.tileIds.includes(tile.id)) && (!discardAction.tileCodes?.length || discardAction.tileCodes.includes(tile.code)));
  const discardRiver = useMemo(() => state ? buildDiscardRiver(state) : [], [state]);
  const claimCount = legalActions.filter((action) => action.type !== "discard" && action.enabled).length;
  const claimState = claimWindowState(state?.lastDiscard, claimCount);
  const claimWindow = claimWindowLabel(state?.lastDiscard, claimCount);
  const visibleActionTimeline = actionFilter === "all" ? actionTimeline : actionTimeline.filter((entry) => entry.status === actionFilter || entry.action === actionFilter || (actionFilter.startsWith("seat") && entry.seat === Number(actionFilter.slice(4))));
  const confirmedDecisionCount = actionTimeline.filter((entry) => entry.status === "confirmed").length;
  const decisionStreak = Math.min(5, confirmedDecisionCount);
  const streakGoal = 3;
  const confirmedCalls = actionTimeline.filter((entry) => entry.status === "confirmed" && ["chi", "pon", "kan"].includes(entry.action)).length;
  const funChallenges = [
    { title: "Streak runner", detail: "Confirm three clean decisions without losing table rhythm.", progress: confirmedDecisionCount, goal: 3 },
    { title: "Call explorer", detail: "Successfully explore two legal chi, pon, or kan opportunities.", progress: confirmedCalls, goal: 2 },
    { title: "Table reader", detail: "Build a five-action confirmed timeline before the hand ends.", progress: confirmedDecisionCount, goal: 5 },
  ] as const;
  const dailyChallengeKey = new Date().toISOString().slice(0, 10);
  const dailyChallengeSeed = dailyChallengeKey.split("-").reduce((sum, part) => sum + Number(part), 0);
  const funChallenge = funChallenges[(dailyChallengeSeed + (state?.handNumber ?? 1) + challengeOffset) % funChallenges.length];
  const funChallengeComplete = funChallenge.progress >= funChallenge.goal;
  const rejectedActionCount = actionTimeline.filter((entry) => entry.status === "rejected").length;
  const momentum = Math.max(0, Math.min(5, confirmedDecisionCount - rejectedActionCount));
  const momentumGoal = 5;
  const momentumComplete = momentum >= momentumGoal;
  const momentumLabel = momentum >= 5 ? "On fire" : momentum >= 3 ? "In rhythm" : momentum > 0 ? "Warming up" : "Fresh table";
  const handRecapHeadline = funChallengeComplete ? `${funChallenge.title} complete` : `${momentumLabel} finish`;
  const handRecapDetail = funChallengeComplete ? "You completed the table objective and built a clear lesson for the next hand." : "Your decision trail is ready to review. Compare one strong line and one turning point before continuing.";
  const decisiveTurn = historyItems.filter((item) => item.snapshot).at(-1)?.snapshot?.turn ?? state?.turn ?? 0;
  const claimExpiryFeedback = actionFeedback?.startsWith("Claim window closed") ?? false;
  const scoreBreakdown = state?.result ? buildScoreBreakdown(state.result, state.result.winner, state.dealer) : null;
  useEffect(() => {
    if (!meldSuccessVisible) return;
    meldSuccessOpacity.setValue(reducedMotion ? 1 : 0.2);
    if (reducedMotion) {
      const timer = setTimeout(() => setMeldSuccessVisible(false), 900);
      return () => clearTimeout(timer);
    }
    Animated.sequence([
      Animated.timing(meldSuccessOpacity, { toValue: 1, duration: 180, useNativeDriver: true }),
      Animated.delay(700),
      Animated.timing(meldSuccessOpacity, { toValue: 0, duration: 240, useNativeDriver: true }),
    ]).start(({ finished }) => { if (finished) setMeldSuccessVisible(false); });
  }, [meldSuccessOpacity, meldSuccessVisible, reducedMotion]);
  useEffect(() => {
    if (selectedDiscard && state?.lastDiscard && selectedDiscard.tile.id !== state.lastDiscard.tile.id && claimState === "open") setSelectedDiscard(null);
  }, [claimState, selectedDiscard, state?.lastDiscard]);
  useEffect(() => {
    const justClosed = previousClaimState.current === "open" && claimState === "closed";
    if (justClosed) {
      setActionFeedback("Claim window closed. The table advanced before a claim was confirmed.");
      setClaimToastVisible(true);
      claimToastOpacity.setValue(reducedMotion ? 1 : 0);
      if (reducedMotion) return;
      Animated.timing(claimToastOpacity, { toValue: 1, duration: 180, useNativeDriver: true }).start();
    }
    previousClaimState.current = claimState;
  }, [claimState, claimToastOpacity, reducedMotion]);

  useEffect(() => {
    if (state?.phase !== "match_complete") {
      completionFeedbackSent.current = false;
      return;
    }
    void safeRemoveItem("mahjong.activeMatchId");
    if (!completionFeedbackSent.current && hapticsEnabled) {
      completionFeedbackSent.current = true;
      haptic.success();
    }
  }, [hapticsEnabled, state?.phase]);
  useEffect(() => {
    if (!id || !actionTimeline.length) return;
    void safeSetItem(`mahjong.actionTimeline:${String(id)}`, JSON.stringify(actionTimeline));
  }, [actionTimeline, id]);

  if (match.isLoading || !state || !player) {
    if (match.error) {
      return <ScreenContainer edges={["top", "bottom", "left", "right"]} className="items-center justify-center p-6"><View><ArenaFeedback tone="error" title="Match could not be loaded" message={match.error.message} /><Pressable onPress={() => void match.refetch()} accessibilityRole="button" style={({ pressed }) => ({ marginTop: 14, borderRadius: 12, backgroundColor: "#D7AA58", paddingHorizontal: 16, paddingVertical: 11, opacity: pressed ? 0.72 : 1 })}><Text className="text-center font-bold text-[#17211F]">Retry match</Text></Pressable></View></ScreenContainer>;
    }
    return <ScreenContainer className="items-center justify-center"><ActivityIndicator color={colors.primary} /></ScreenContainer>;
  }

  const turnStatus = describeTurnStatus(state, 0);
  const syncStatus = describeGameplaySync({ isFetching: match.isFetching, hasError: Boolean(match.error), networkOffline: networkStatus === "offline", dataUpdatedAt: match.dataUpdatedAt });
  const waitingForTurn = !isYourTurn || submit.isPending;
  const canAct = Boolean(isYourTurn && syncStatus.actionSafe && !legal.isFetching && !legal.error && !submit.isPending);
  const send = (action: ActionEnvelope, isRetry = false) => { if (!syncStatus.actionSafe) { setActionFeedback(syncStatus.detail); return; } if (submit.isPending || optimisticAction) { setActionFeedback("A previous action is still awaiting confirmation. Duplicate submissions are paused until the table responds."); return; } lastActionRef.current = action; setRetryAction(null); setOptimisticAction(action.type); setActionTimeline((current) => appendActionLifecycle(current, createActionLifecycleEntry(action, isRetry ? "retrying" : "pending", undefined, language))); setActionFeedback(describeActionIntent(action)); submit.mutate({ id: String(id), action }); };
  const claimChoices = (action: LegalAction) => getMultiTileChoices(action.type, player?.hand ?? [], state?.lastDiscard?.tile);
  const selectedTileIsAllowed = (action: LegalAction) => {
    if (!selectedTile) return false;
    const code = selectedTileData?.code;
    return (!action.tileIds?.length || action.tileIds.includes(selectedTile)) && (!action.tileCodes?.length || Boolean(code && action.tileCodes.includes(code)));
  };
  const actionNeedsSelection = (action: LegalAction) => {
    if (action.type === "discard" || action.type === "riichi") return !selectedTile || !selectedTileIsAllowed(action);
    if (["kan", "pon", "chi"].includes(action.type)) return claimChoices(action).length === 0;
    return false;
  };
  const canSubmitDiscard = Boolean(discardAction?.enabled && selectedTile && selectedTileIsAllowed(discardAction) && canAct);
  const canSubmitLegalAction = (action: LegalAction) => action.enabled && canAct && !actionNeedsSelection(action);
  const pendingChoices = pendingClaim ? claimChoices(pendingClaim) : [];
  const submitLegalAction = (action: LegalAction, selectedIds?: string[]) => {
    const choices = claimChoices(action);
    if (choices.length > 1 && !selectedIds?.length) {
      setPendingClaim(action);
      setSelectedClaimTiles([]);
      return;
    }
    const resolvedIds = selectedIds?.length ? selectedIds : (["discard", "riichi"].includes(action.type) && selectedTile ? [selectedTile] : action.tileIds ?? (choices[0]?.map((tile) => tile.id) ?? undefined));
    if (!syncStatus.actionSafe) { setActionFeedback(syncStatus.detail); return; }
    if (!action.enabled || !isYourTurn || !resolvedIds?.length && ["discard", "riichi", "kan", "pon", "chi"].includes(action.type)) {
      setActionFeedback(actionNeedsSelection(action) ? `${action.label} needs the required tile selection first.` : action.reason ?? "This action is not available right now.");
      return;
    }
    if (action.type === "discard" && confirmBeforeDiscard && !selectedIds?.length) {
      setPendingDiscardAction(action);
      return;
    }
    setPendingDiscardAction(null);
    setPendingClaim(null);
    setSelectedClaimTiles([]);
    send({ type: action.type, seat: 0, tileIds: resolvedIds, tileCodes: action.tileCodes, tsumogiri: action.type === "discard" ? false : undefined });
  };

  return (
    <ScreenContainer edges={["top", "bottom", "left", "right"]} className="bg-[#123C35]" containerClassName="bg-[#123C35]">
      <ScrollView contentContainerStyle={{ padding: 16, paddingBottom: 28 }}>
        <View className="gap-4">
          <View className="gap-2">
            <View className="flex-row items-center justify-between">
              <Pressable onPress={() => router.back()} hitSlop={8} accessibilityRole="button" accessibilityLabel="Leave table" accessibilityHint="Returns to the previous screen without changing the match" style={({ pressed }) => ({ minHeight: 36, justifyContent: "center", opacity: pressed ? 0.65 : 1 })}><Text className="text-sm font-semibold text-[#F7F0E3]">‹ Leave table</Text></Pressable>
              <View className="rounded-full border border-[#2E6A59] bg-[#17493F] px-3 py-2"><Text className="text-xs font-bold text-[#F7F0E3]">{state.wall.length} wall</Text></View>
            </View>
            <View className="flex-row items-center justify-between"><Text accessibilityRole="header" className="text-xs font-bold uppercase tracking-wider text-[#D7AA58]">{state.roundWind} {state.handNumber} · Turn {state.turn}</Text><Text className={isYourTurn ? "text-xs font-bold uppercase tracking-wider text-[#D7AA58]" : "text-xs font-semibold uppercase tracking-wider text-[#B9D4C8]"}>{isYourTurn ? "Your turn" : `Seat ${state.currentSeat} thinking`}</Text></View>
          </View>

          <Animated.View style={{ opacity: transitionOpacity, transform: [{ translateY: transitionOpacity.interpolate({ inputRange: [0.94, 1], outputRange: [3, 0] }) }] }} className={turnStatus.tone === "active" ? "rounded-2xl border border-[#D7AA58] bg-[#274F43] p-4" : turnStatus.tone === "complete" ? "rounded-2xl border border-[#B8D9C9] bg-[#E8F1ED] p-4" : "rounded-2xl border border-[#2E6A59] bg-[#17493F] p-4"} accessibilityRole="summary"><View className="flex-row items-center justify-between"><View><Text className={turnStatus.tone === "complete" ? "text-xs font-bold uppercase tracking-widest text-[#2E6A59]" : "text-xs font-bold uppercase tracking-widest text-[#D7AA58]"}>Table status</Text><Text className={turnStatus.tone === "complete" ? "mt-1 text-lg font-bold text-[#17211F]" : "mt-1 text-lg font-bold text-[#F7F0E3]"}>{turnStatus.label}</Text></View><Text className={turnStatus.tone === "active" ? "rounded-full bg-[#D7AA58] px-3 py-1 text-xs font-bold text-[#17211F]" : "rounded-full bg-[#123C35] px-3 py-1 text-xs font-bold text-[#B9D4C8]"}>{state.turn} / {state.wall.length} wall</Text></View><Text className={turnStatus.tone === "complete" ? "mt-2 text-sm leading-5 text-[#2E6A59]" : "mt-2 text-sm leading-5 text-[#B9D4C8]"}>{turnStatus.detail}</Text><View className="mt-3 rounded-xl bg-[#123C35] p-3"><View className="flex-row items-center justify-between"><View><Text className="text-[10px] font-bold uppercase tracking-widest text-[#D7AA58]">{t("dailyChallenge")}</Text><Text className="mt-1 text-sm font-bold text-[#F7F0E3]">{funChallenge.title}</Text></View><Text className="text-lg font-bold text-[#F7F0E3]">{Math.min(funChallenge.progress, funChallenge.goal)}/{funChallenge.goal}</Text></View><Text className="mt-1 text-xs leading-4 text-[#B9D4C8]">{funChallenge.detail}</Text><View className="mt-2 h-1.5 overflow-hidden rounded-full bg-[#0B241F]"><View className="h-full rounded-full bg-[#D7AA58]" style={{ width: `${Math.min(100, (funChallenge.progress / funChallenge.goal) * 100)}%` }} /></View><Pressable onPress={() => { setChallengeOffset((current) => (current + 1) % funChallenges.length); if (hapticsEnabled) haptic.light(); }} accessibilityRole="button" accessibilityLabel="Choose a different Arena challenge" accessibilityHint="Cycles to a different gameplay objective for this table" style={({ pressed }) => ({ marginTop: 10, alignSelf: "flex-start", borderRadius: 10, borderWidth: 1, borderColor: "#D7AA58", paddingHorizontal: 10, paddingVertical: 7, opacity: pressed ? 0.72 : 1 })}><Text className="text-[10px] font-bold uppercase tracking-wide text-[#D7AA58]">{t("newObjective")}</Text></Pressable></View><View className="mt-3 rounded-xl bg-[#123C35] p-3"><View className="flex-row items-center justify-between"><View><Text className="text-[10px] font-bold uppercase tracking-widest text-[#D7AA58]">{t("tableMomentum")}</Text><Text className="mt-1 text-xs font-bold text-[#B9D4C8]">{momentumLabel}</Text></View><Text className="text-xs font-bold text-[#F7F0E3]">{momentum}/{momentumGoal}</Text></View><Text className="mt-1 text-xs text-[#B9D4C8]">Confirmed decisions build momentum; rejected moves give you room to reset.</Text><View className="mt-2 h-1.5 overflow-hidden rounded-full bg-[#0B241F]"><View className="h-full rounded-full bg-[#77C69B]" style={{ width: `${(momentum / momentumGoal) * 100}%` }} /></View></View><View className="mt-3 flex-row items-center justify-between rounded-xl bg-[#123C35] p-3"><View className="flex-1"><Text className={syncStatus.tone === "offline" ? "text-xs font-bold text-[#F3B4A5]" : "text-xs font-bold text-[#D7AA58]"}>{syncStatus.label}</Text><Text className="mt-1 text-[10px] leading-4 text-[#B9D4C8]">{syncStatus.detail} · {syncStatus.ageLabel}</Text></View>{syncStatus.needsRetry ? <Pressable onPress={() => { void match.refetch(); void legal.refetch(); void audit.refetch(); }} accessibilityRole="button" accessibilityLabel="Refresh table synchronization" style={({ pressed }) => ({ marginLeft: 10, borderRadius: 10, backgroundColor: "#D7AA58", paddingHorizontal: 11, paddingVertical: 8, opacity: pressed ? 0.72 : 1 })}><Text className="text-xs font-bold text-[#17211F]">Sync now</Text></Pressable> : null}</View></Animated.View>

          <View className="rounded-[28px] border border-[#2E6A59] bg-[#17493F] p-3">
            <View className="mb-3 flex-row justify-between">
              <View><Text className="font-bold text-[#F7F0E3]">Sora</Text><Text className="text-xs text-[#B9D4C8]">North · 25,000</Text></View>
              <View className="items-end"><Text className="font-bold text-[#F7F0E3]">Ren</Text><Text className="text-xs text-[#B9D4C8]">West · 25,000</Text></View>
            </View>
            <View className="h-44 items-center justify-center rounded-2xl bg-[#123C35]">
              <Text className="text-5xl text-[#D7AA58]">東</Text>
              <Text className="mt-2 text-xs uppercase tracking-widest text-[#B9D4C8]">Your AI table</Text>
            </View>
            <View className="mt-3 flex-row items-center justify-between"><Text className="font-bold text-[#F7F0E3]">Mika · South · 25,000</Text><Text className="text-xs text-[#B9D4C8]">Balanced policy</Text></View>
          </View>

          <View className="rounded-2xl border border-[#2E6A59] bg-[#17493F] p-4"><View className="flex-row items-center justify-between"><View><Text className="text-xs font-bold uppercase tracking-widest text-[#D7AA58]">Match brief</Text><Text className="mt-1 text-lg font-bold text-[#F7F0E3]">{state.roundWind} · hand {state.handNumber}</Text></View><Text className="text-xs font-semibold text-[#B9D4C8]">{state.wall.length} tiles left</Text></View><View className="mt-3 flex-row gap-2"><View className="flex-1 rounded-xl bg-[#123C35] p-3"><Text className="text-[10px] uppercase text-[#B9D4C8]">Your score</Text><Text className="mt-1 text-lg font-bold text-[#F7F0E3]">{player.score.toLocaleString()}</Text></View><View className="flex-1 rounded-xl bg-[#123C35] p-3"><Text className="text-[10px] uppercase text-[#B9D4C8]">Legal actions</Text><Text className="mt-1 text-lg font-bold text-[#F7F0E3]">{enabledLegalActionCount} ready</Text></View></View><View className="mt-3 flex-row gap-2"><Pressable onPress={() => router.push({ pathname: "/review", params: { matchId: String(id) } })} accessibilityRole="button" accessibilityLabel="Open match review" style={({ pressed }) => ({ flex: 1, borderRadius: arenaTokens.radius.md, backgroundColor: arenaTokens.color.successSurface, padding: 10, opacity: pressed ? 0.7 : 1 })}><Text className="text-center text-xs font-bold text-[#2E6A59]">Review replay</Text></Pressable><Pressable onPress={() => router.push("/history")} accessibilityRole="button" accessibilityLabel="Open match history" style={({ pressed }) => ({ flex: 1, borderRadius: arenaTokens.radius.md, borderWidth: 1, borderColor: "rgba(212,175,112,0.4)", padding: 10, opacity: pressed ? 0.7 : 1 })}><Text className="text-center text-xs font-bold text-[#D7AA58]">History</Text></Pressable></View>          </View>

          {player.melds.length > 0 ? <ArenaCard eyebrow="Open hand" title={`${player.melds.length} meld${player.melds.length === 1 ? "" : "s"}`} tone="jade"><Text className="text-sm leading-5 text-[#B9D4C8]">Claimed tiles remain visible so the AI can account for open-hand value and defense.</Text><View className="mt-3 gap-2">{player.melds.map((meld, index) => <View key={`${meld.type}-${index}`} className="flex-row items-center gap-2 rounded-xl bg-[#123C35] p-3"><Text className="w-12 text-xs font-bold uppercase text-[#D7AA58]">{meld.type}</Text><Text className="flex-1 text-sm font-bold text-[#F7F0E3]">{meld.tiles.map((tile) => tile.code).join(" · ")}</Text><Text className="text-[10px] uppercase text-[#B9D4C8]">{meld.open ? "Open" : "Closed"}</Text></View>)}</View></ArenaCard> : null}

          {state.lastDiscard || discardRiver.length ? <View className="rounded-2xl border border-[#2E6A59] bg-[#123C35] p-4"><View className="flex-row items-center justify-between"><Text className="text-xs font-bold uppercase tracking-widest text-[#D7AA58]">Discard river</Text><Text className="text-[10px] font-bold uppercase tracking-wide text-[#B9D4C8]">{discardRiver.length} visible</Text></View><Text className="mt-1 text-sm font-bold text-[#F7F0E3]">{state.lastDiscard ? `Latest · seat ${state.lastDiscard.seat} · ${state.lastDiscard.tile.code}${state.lastDiscard.riichiDeclaration ? " · riichi" : ""}` : "No discard yet"}</Text><View className="mt-2 flex-row items-center gap-2"><Text className={`rounded-full px-2 py-1 text-[10px] font-bold uppercase tracking-wide ${claimState === "open" ? "bg-[#D7AA58] text-[#17211F]" : claimState === "closed" ? "bg-[#8B3A2B] text-[#F7F0E3]" : "bg-[#2E6A59] text-[#F7F0E3]"}`}>{claimState === "open" ? "Claim open" : claimState === "closed" ? "Claim closed" : "No window"}</Text><Text className="flex-1 text-xs text-[#B9D4C8]">{claimWindow}</Text>{claimState === "closed" && state.lastDiscard ? <Pressable onPress={() => setSelectedDiscard(discardRiver.find((entry) => entry.tile.id === state.lastDiscard?.tile.id) ?? null)} accessibilityRole="button" accessibilityLabel="Inspect the closed claim discard" style={({ pressed }) => ({ borderRadius: 9, backgroundColor: "#D7AA58", paddingHorizontal: 9, paddingVertical: 6, opacity: pressed ? 0.72 : 1 })}><Text className="text-[10px] font-bold text-[#17211F]">Inspect</Text></Pressable> : null}</View><View className="mt-3 flex-row flex-wrap gap-2">{discardRiver.map((discard) => <Pressable key={`${discard.seat}-${discard.turn}-${discard.tile.id}`} onPress={() => { if (hapticsEnabled) haptic.selection(); setSelectedDiscard(selectedDiscard?.tile.id === discard.tile.id ? null : discard); }} accessibilityRole="button" accessibilityLabel={`${discard.tile.code}, ${discard.seatLabel}, turn ${discard.turn}${discard.riichiDeclaration ? ", riichi declaration" : ""}`} accessibilityHint="Shows discard context and replay options" accessibilityState={{ selected: selectedDiscard?.tile.id === discard.tile.id }} style={({ pressed }) => ({ borderRadius: 12, opacity: pressed ? 0.72 : 1, transform: [{ scale: pressed ? 0.96 : 1 }] })}><View className={`rounded-xl border-2 px-2 py-2 ${selectedDiscard?.tile.id === discard.tile.id ? "border-[#FFF0D5]" : "border-transparent"} ${seatAccent(discard.seat) === "brass" ? "bg-[#D7AA58]" : seatAccent(discard.seat) === "jade" ? "bg-[#2E6A59]" : seatAccent(discard.seat) === "paper" ? "bg-[#F7F0E3]" : "bg-[#8B3A2B]"}`}><Text className={`text-xs font-bold ${seatAccent(discard.seat) === "paper" ? "text-[#17211F]" : "text-[#F7F0E3]"}`}>{discard.tile.code}</Text><Text className={`text-[9px] uppercase ${seatAccent(discard.seat) === "paper" ? "text-[#7B6B5A]" : "text-[#B9D4C8]"}`}>{discard.seat} · T{discard.turn}</Text></View></Pressable>)}</View>{selectedDiscard ? <View className="mt-3 rounded-xl border border-[#B87843] bg-[#FFF8EC] p-3"><View className="flex-row items-center justify-between"><View><Text className="text-xs font-bold uppercase tracking-wide text-[#8B5A2B]">Selected discard</Text><Text className="mt-1 text-sm font-bold text-[#17211F]">{selectedDiscard.tile.code} · {selectedDiscard.seatLabel}</Text></View><Text className="text-xs font-bold text-[#8B5A2B]">Turn {selectedDiscard.turn}</Text></View><Text className="mt-2 text-xs leading-4 text-[#7B6B5A]">{selectedDiscard.riichiDeclaration ? "This discard included a riichi declaration. " : ""}{selectedDiscard.tsumogiri ? "Tsumogiri." : "Chosen discard."} Use the replay review to inspect the surrounding decision context.</Text><Pressable onPress={() => router.push({ pathname: "/review", params: { matchId: String(id), turn: String(selectedDiscard.turn), tile: selectedDiscard.tile.code } })} accessibilityRole="button" accessibilityLabel={`Review decision around turn ${selectedDiscard.turn}`} style={({ pressed }) => ({ marginTop: 10, alignSelf: "flex-start", borderRadius: 10, backgroundColor: "#D7AA58", paddingHorizontal: 12, paddingVertical: 9, opacity: pressed ? 0.72 : 1 })}><Text className="text-xs font-bold text-[#17211F]">Review this turn</Text></Pressable></View> : null}</View> : null}

          {state.result ? <ArenaCard eyebrow="Hand complete" title={`${state.result.method === "tsumo" ? "Tsumo" : "Ron"} · ${state.result.points.toLocaleString()} points`} tone="paper"><Text className="text-sm leading-5 text-[#7B6B5A]">The backend resolved the hand with {state.result.han} han and {state.result.fu} fu.</Text><View className="mt-3 rounded-xl border border-[#D7AA58] bg-[#FFF0D5] p-3" accessibilityRole="summary"><Text className="text-[10px] font-bold uppercase tracking-widest text-[#8B5A2B]">{t("yourHand")} recap</Text><Text className="mt-1 text-lg font-bold text-[#17211F]">{handRecapHeadline}</Text><Text className="mt-1 text-xs leading-4 text-[#7B6B5A]">{handRecapDetail}</Text><View className="mt-3 flex-row gap-2"><View className="flex-1 rounded-lg bg-[#FFF8EC] px-2 py-2"><Text className="text-[10px] uppercase text-[#7B6B5A]">Run grade</Text><Text className="font-bold text-[#17211F]">{momentumLabel}</Text></View><View className="flex-1 rounded-lg bg-[#FFF8EC] px-2 py-2"><Text className="text-[10px] uppercase text-[#7B6B5A]">Confirmed</Text><Text className="font-bold text-[#17211F]">{confirmedDecisionCount}</Text></View><View className="flex-1 rounded-lg bg-[#FFF8EC] px-2 py-2"><Text className="text-[10px] uppercase text-[#7B6B5A]">Momentum</Text><Text className="font-bold text-[#17211F]">{momentum}/{momentumGoal}</Text></View></View></View><View className="mt-3 flex-row flex-wrap gap-2"><View className="rounded-xl bg-[#FFF8EC] px-3 py-2"><Text className="text-[10px] uppercase text-[#7B6B5A]">Open melds</Text><Text className="font-bold text-[#17211F]">{player.melds.length}</Text></View><View className="rounded-xl bg-[#FFF8EC] px-3 py-2"><Text className="text-[10px] uppercase text-[#7B6B5A]">Win method</Text><Text className="font-bold capitalize text-[#17211F]">{state.result.method}</Text></View><View className="rounded-xl bg-[#FFF8EC] px-3 py-2"><Text className="text-[10px] uppercase text-[#7B6B5A]">Riichi sticks</Text><Text className="font-bold text-[#17211F]">{state.riichiSticks}</Text></View></View>{scoreBreakdown ? <View className="mt-3 rounded-xl border border-[#E7D5B8] bg-[#FFF8EC] p-3" accessibilityLabel="Transparent score breakdown"><Text className="text-xs font-bold uppercase tracking-widest text-[#8B5A2B]">How Sensei scored it</Text><View className="mt-2 gap-2">{scoreBreakdown.lines.map((line) => <View key={line.label} className="flex-row items-center justify-between"><Text className="flex-1 text-sm text-[#17211F]">{line.label}</Text><Text className="text-sm font-bold text-[#8B5A2B]">{line.detail}</Text></View>)}</View><View className="mt-3 flex-row flex-wrap gap-2"><View className="rounded-lg bg-[#F7F0E3] px-2 py-1"><Text className="text-[10px] uppercase text-[#7B6B5A]">Base points</Text><Text className="font-bold text-[#17211F]">{scoreBreakdown.basePoints.toLocaleString()}</Text></View><View className="rounded-lg bg-[#F7F0E3] px-2 py-1"><Text className="text-[10px] uppercase text-[#7B6B5A]">Payment</Text><Text className="font-bold text-[#17211F]">{scoreBreakdown.paymentLabel}</Text></View></View><Text className="mt-2 text-xs leading-4 text-[#7B6B5A]">{scoreBreakdown.formula}</Text></View> : null}<View className="mt-3 flex-row flex-wrap gap-2">{Object.entries(state.result.scoreDeltas).map(([seat, delta]) => <View key={seat} className="rounded-xl bg-[#FFF8EC] px-3 py-2"><Text className="text-[10px] uppercase text-[#7B6B5A]">Seat {seat}</Text><Text className={`font-bold ${delta >= 0 ? "text-[#2E6A59]" : "text-[#9B2414]"}`}>{delta >= 0 ? "+" : ""}{delta.toLocaleString()}</Text></View>)}</View><View className="mt-3 rounded-xl border border-[#E7D5B8] bg-[#FFF8EC] p-3"><Text className="text-xs font-bold uppercase tracking-widest text-[#8B5A2B]">Rematch choice</Text><Text className="mt-1 text-xs leading-4 text-[#7B6B5A]">Keep the table rhythm or bring a new Arena objective into the next hand.</Text><Pressable onPress={() => { setChallengeOffset((current) => (current + 1) % funChallenges.length); if (hapticsEnabled) haptic.light(); setActionFeedback("A fresh Arena objective is queued for the next hand."); }} accessibilityRole="button" accessibilityLabel="Queue a fresh Arena objective for the next hand" style={({ pressed }) => ({ marginTop: 10, alignSelf: "flex-start", borderRadius: 10, borderWidth: 1, borderColor: "#B87843", paddingHorizontal: 10, paddingVertical: 7, opacity: pressed ? 0.72 : 1 })}><Text className="text-[10px] font-bold uppercase tracking-wide text-[#8B5A2B]">Queue fresh objective</Text></Pressable></View><View className="mt-3 flex-row flex-wrap gap-2"><Pressable onPress={() => router.push({ pathname: "/review", params: { matchId: String(id), turn: String(decisiveTurn) } })} accessibilityRole="button" accessibilityLabel={`Replay decisive turn ${decisiveTurn}`} style={({ pressed }) => ({ flex: 1, minWidth: "46%", borderRadius: 12, backgroundColor: "#E8F1ED", padding: 12, opacity: pressed ? 0.72 : 1 })}><Text className="text-center text-sm font-bold text-[#2E6A59]">Play decisive turn</Text></Pressable><Pressable onPress={() => { setOptimisticAction("pass"); setActionFeedback("Starting the next hand. Scores and dealer state are being preserved."); advanceRound.mutate({ id: String(id) }); }} disabled={advanceRound.isPending || state.phase === "match_complete"} accessibilityRole="button" accessibilityLabel="Start next hand" style={({ pressed }) => ({ flex: 1, borderRadius: 12, backgroundColor: "#D7AA58", padding: 12, opacity: advanceRound.isPending || state.phase === "match_complete" ? 0.45 : pressed ? 0.72 : 1 })}><Text className="text-center text-sm font-bold text-[#17211F]">{state.phase === "match_complete" ? "Match complete" : advanceRound.isPending ? "Starting…" : "Start next hand"}</Text></Pressable><Pressable onPress={() => router.push({ pathname: "/review", params: { matchId: String(id) } })} accessibilityRole="button" style={({ pressed }) => ({ flex: 1, minWidth: "46%", borderRadius: 12, borderWidth: 1, borderColor: "#B87843", padding: 12, opacity: pressed ? 0.72 : 1 })}><Text className="text-center text-sm font-bold text-[#B87843]">Review hand</Text></Pressable>{state.phase === "match_complete" ? <Pressable onPress={() => router.replace("/")} accessibilityRole="button" accessibilityLabel="Return home after match completion" style={({ pressed }) => ({ flex: 1, borderRadius: 12, borderWidth: 1, borderColor: "#2E6A59", padding: 12, opacity: pressed ? 0.72 : 1 })}><Text className="text-center text-sm font-bold text-[#2E6A59]">Return home</Text></Pressable> : null}</View></ArenaCard> : null}

          {aiMatchReport.data && aiMatchReport.data.decisions > 0 ? <ArenaCard eyebrow="AI table report" title={`${aiMatchReport.data.decisions} decisions recorded`} tone="jade"><Text className="text-sm leading-5 text-[#B9D4C8]">Review confidence and policy behavior after the hand resolves.</Text><View className="mt-3 flex-row flex-wrap gap-2">{Object.entries(aiMatchReport.data.bySeat).map(([seat, report]) => <View key={seat} className="rounded-xl bg-[#123C35] px-3 py-2"><Text className="text-[10px] uppercase text-[#B9D4C8]">Seat {seat} · {report.policy}</Text><Text className="font-bold text-[#F7F0E3]">{Math.round(report.averageConfidence * 100)}% confidence</Text></View>)}</View></ArenaCard> : null}

          {historyItems.length ? <ArenaCard eyebrow="Live action history" title="What just changed" tone="jade"><Pressable onPress={() => { if (hapticsEnabled) haptic.light(); setShowAudit(!showAudit); }} accessibilityRole="button" accessibilityLabel={showAudit ? "Collapse full audit timeline" : "Expand full audit timeline"} accessibilityState={{ expanded: showAudit }} style={({ pressed }) => ({ marginTop: 12, borderRadius: 12, backgroundColor: "rgba(255,255,255,0.06)", padding: 10, opacity: pressed ? 0.72 : 1 })}><Text className="text-xs font-bold text-[#D7AA58]">{showAudit ? "Hide full audit" : "Show full audit"}</Text></Pressable><View style={{ gap: 10, marginTop: 12 }}>{(showAudit ? historyItems : historyItems.slice(0, 3)).map((item) => <View key={item.key} accessibilityLabel={`${item.title}, ${item.detail}, ${item.time}`} style={{ flexDirection: "row", alignItems: "center", gap: 10 }}><View style={{ width: 26, height: 26, alignItems: "center", justifyContent: "center", borderRadius: 999, backgroundColor: "rgba(212,175,112,0.18)" }}><Text style={{ color: "#D7AA58", fontSize: 11, fontWeight: "800" }}>{item.sequence}</Text></View><View style={{ flex: 1 }}><Text className="text-sm font-bold text-[#F7F0E3] capitalize">{item.title}</Text><Text className="text-xs text-[#B9D4C8]">{item.detail} · {item.time} · #{item.stateHash}</Text>{showAudit && item.snapshot ? <Text className="mt-1 text-[10px] leading-4 text-[#D7AA58]">Turn {item.snapshot.turn} · {item.snapshot.wallCount} wall · {item.snapshot.score?.toLocaleString() ?? "—"} pts · {item.snapshot.visibleHand.join(" ")}</Text> : null}</View></View>)}</View></ArenaCard> : audit.isLoading ? <ArenaCard eyebrow="Live action history" title="Syncing table events" tone="jade"><Text className="mt-2 text-sm text-[#B9D4C8]">Waiting for the latest backend event stream.</Text></ArenaCard> : null}

          <View className="rounded-2xl bg-[#F7F0E3] p-3">
            <View className="mb-3 flex-row items-center justify-between"><Text className="font-bold text-[#17211F]">{t("yourHand")}</Text><Text className="text-xs text-[#7B6B5A]">{player.hand.length} tiles · shanten estimate {Math.max(0, Math.round(player.hand.length / 3) - 3)}</Text></View>
            {selectedTileData ? <View className="mb-3 flex-row items-center rounded-xl bg-[#FFF8EC] p-3"><View className="flex-1"><Text className="text-xs font-bold uppercase tracking-wide text-[#8B5A2B]">Selected discard</Text><Text className="mt-1 text-sm font-bold text-[#17211F]">{selectedTileData.code} · {discardAction?.enabled && selectedTileIsAllowed(discardAction) ? "legal candidate" : "review legality before submitting"}</Text></View><Pressable onPress={() => setSelectedTile(undefined)} accessibilityRole="button" accessibilityLabel="Clear selected discard" accessibilityHint="Removes the discard candidate without submitting an action" style={({ pressed }) => ({ borderRadius: 10, backgroundColor: "#F7F0E3", paddingHorizontal: 10, paddingVertical: 8, opacity: pressed ? 0.72 : 1 })}><Text className="text-xs font-bold text-[#8B5A2B]">Clear</Text></Pressable></View> : <Text className="mb-3 text-xs text-[#7B6B5A]">Tap a tile to select it. Green borders mark backend-approved discard candidates when the table is ready.</Text>}
            <View className="flex-row flex-wrap gap-1">
              {tileCodes.map((code, index) => { const tile = player.hand[index]; return <Tile key={`${code}-${index}`} code={code} legal={tile ? tileIsLegalForDiscard(tile) : false} selected={selectedTile === tile?.id} hapticsEnabled={hapticsEnabled} disabled={!canAct} language={language} onPress={() => tile && setSelectedTile(tile.id)} />; })}
            </View>
          </View>

          <View className="rounded-2xl border border-[#2E6A59] bg-[#0F302B] p-3">
            <View className="mb-2 flex-row items-center justify-between"><Text className="text-xs font-bold uppercase tracking-widest text-[#D7AA58]">Your move</Text><Text className="text-[10px] font-semibold uppercase tracking-wide text-[#B9D4C8]">{selectedTileData ? `Selected ${selectedTileData.code}` : isYourTurn ? "Choose a tile" : "Waiting for table"}</Text></View><Text className="mb-3 text-xs leading-4 text-[#B9D4C8]">{submit.isPending || optimisticAction ? "Action sent. Waiting for the confirmed table state." : !isYourTurn ? `Seat ${state.currentSeat} is thinking. Your controls will unlock automatically.` : selectedTileData ? "Review the selected tile, ask Copilot, or discard when ready." : "Select a tile to prepare a discard."}</Text>
            <View className="flex-row gap-2">
              <Pressable onPress={() => { setShowCopilot(true); setSelectedComparisonMode(null); analysis.reset(); modeComparison.reset(); analysis.mutate({ id: String(id), seat: 0, policy: "balanced", useLLM: false, coachingMode }); modeComparison.mutate({ id: String(id), seat: 0 }); }} accessibilityRole="button" accessibilityLabel="Ask Copilot for a decision snapshot" accessibilityHint="Opens an explainable decision comparison" style={({ pressed }) => ({ flex: 1, minHeight: 54, borderRadius: 16, backgroundColor: "#D7AA58", padding: 16, alignItems: "center", justifyContent: "center", opacity: pressed ? 0.78 : 1, transform: [{ scale: pressed ? 0.98 : 1 }] })}><Text className="text-center font-bold text-[#17211F]">{analysis.isPending ? "Thinking…" : "Ask Copilot"}</Text></Pressable>
              <Pressable onPress={() => selectedTile && discardAction && submitLegalAction(discardAction)} disabled={!canSubmitDiscard || waitingForTurn} accessibilityRole="button" accessibilityLabel="Discard selected tile" accessibilityHint={discardAction?.reason ?? "Submits the selected tile as a backend-approved discard"} accessibilityState={{ disabled: !canSubmitDiscard || waitingForTurn }} style={({ pressed }) => ({ flex: 1, minHeight: 54, borderRadius: 16, backgroundColor: "#F7F0F3", padding: 16, alignItems: "center", justifyContent: "center", opacity: !canSubmitDiscard || waitingForTurn ? 0.45 : pressed ? 0.78 : 1, transform: [{ scale: pressed ? 0.98 : 1 }] })}><Text className="text-center font-bold text-[#17211F]">{!isYourTurn ? "Waiting" : !discardAction?.enabled ? "Unavailable" : submit.isPending ? "Sending…" : "Discard"}</Text></Pressable>
            </View>
          </View>

          {actionFeedback ? <ArenaFeedback tone={submit.error ? "error" : claimExpiryFeedback ? "warning" : "success"} title={submit.error ? "Action needs attention" : claimExpiryFeedback ? "Claim window closed" : optimisticAction ? "Action in progress" : "Action accepted"} message={optimisticAction ? `${actionFeedback} The table is locking duplicate inputs until the server confirms it.` : actionFeedback} /> : null}
          {confirmedDecisionCount > 0 && confirmedDecisionCount % streakGoal === 0 ? <ArenaFeedback tone="success" title="Sensei streak unlocked" message={`You confirmed ${confirmedDecisionCount} clean decisions. Keep the table rhythm going.`} /> : null}
          {funChallengeComplete ? <ArenaFeedback tone="success" title="Arena challenge complete" message={`${funChallenge.title} complete. Your next table state will bring a fresh objective.`} /> : null}
          {momentumComplete ? <ArenaFeedback tone="success" title="Momentum mastery" message="Five confirmed decisions in rhythm. You are reading the table with confidence." /> : null}
          {meldSuccessVisible ? <Animated.View accessibilityRole="alert" style={{ opacity: meldSuccessOpacity, borderRadius: 14, borderWidth: 1, borderColor: "#D7AA58", backgroundColor: "#FFF0D5", paddingHorizontal: 14, paddingVertical: 10 }}><Text className="text-center text-xs font-bold uppercase tracking-wide text-[#8B5A2B]">Meld completed · table state refreshing</Text></Animated.View> : null}
          {claimToastVisible ? <Animated.View accessibilityRole="alert" style={{ opacity: claimToastOpacity, transform: [{ translateY: claimToastOpacity.interpolate({ inputRange: [0, 1], outputRange: [-4, 0] }) }], borderRadius: 999, borderWidth: 1, borderColor: "#B87843", backgroundColor: "#FFF0D5", paddingHorizontal: 14, paddingVertical: 9 }}><View className="flex-row items-center justify-between gap-3"><Text className="flex-1 text-xs font-bold text-[#8B5A2B]">Claim expired · inspect the latest discard</Text>{selectedDiscard ? <Pressable onPress={() => setSelectedDiscard(selectedDiscard)} accessibilityRole="button" accessibilityLabel="Inspect the expired claim discard" style={({ pressed }) => ({ borderRadius: 999, backgroundColor: "#D7AA58", paddingHorizontal: 10, paddingVertical: 6, opacity: pressed ? 0.72 : 1 })}><Text className="text-[10px] font-bold text-[#17211F]">Inspect</Text></Pressable> : null}</View></Animated.View> : null}
          {retryAction && syncStatus.actionSafe ? <Pressable onPress={() => send(retryAction, true)} disabled={submit.isPending} accessibilityRole="button" accessibilityLabel="Retry the last Mahjong action" style={({ pressed }) => ({ borderRadius: 12, borderWidth: 1, borderColor: "#D7AA58", padding: 11, opacity: submit.isPending ? 0.45 : pressed ? 0.72 : 1 })}><Text className="text-center text-xs font-bold text-[#D7AA58]">Retry last action</Text></Pressable> : null}
          {actionTimeline.length ? <ArenaCard eyebrow="Action queue" title="What the table confirmed" tone="jade"><View className="mb-3 flex-row flex-wrap gap-2">{ACTION_FILTER_OPTIONS.map((filter) => <Pressable key={filter} onPress={() => setActionFilter(filter)} accessibilityRole="button" accessibilityLabel={`Show ${filter} actions`} accessibilityState={{ selected: actionFilter === filter }} style={({ pressed }) => ({ width: "23%", borderRadius: 10, backgroundColor: actionFilter === filter ? "#D7AA58" : "rgba(255,255,255,0.06)", paddingVertical: 8, opacity: pressed ? 0.72 : 1 })}><Text className={`text-center text-[10px] font-bold uppercase ${actionFilter === filter ? "text-[#17211F]" : "text-[#B9D4C8]"}`}>{filter.startsWith("seat") ? `Seat ${filter.slice(4)}` : filter}</Text></Pressable>)}</View><View className="gap-2">{visibleActionTimeline.slice(-4).reverse().map((entry) => <View key={entry.id} className="flex-row items-center gap-3 rounded-xl bg-[#123C35] p-3" style={{ borderLeftWidth: entry.seat !== undefined ? 3 : 0, borderLeftColor: entry.seat === 0 ? "#B87843" : entry.seat === 1 ? "#2E6A59" : entry.seat === 2 ? "#6B7F9E" : "#9B5B54" }} accessibilityLabel={`${entry.label}, ${entry.status}, ${entry.detail}`}><View className={`h-8 w-8 items-center justify-center rounded-full ${entry.status === "confirmed" ? "bg-[#2E6A59]" : entry.status === "rejected" ? "bg-[#8B3A2B]" : "bg-[#8B6A2A]"}`}><Text className="text-xs font-bold text-[#F7F0E3]">{entry.status === "confirmed" ? "✓" : entry.status === "rejected" ? "!" : "…"}</Text></View><View className="flex-1"><Text className="text-sm font-bold text-[#F7F0E3]">{entry.seat !== undefined ? `Seat ${entry.seat} · ` : ""}{entry.label} · {entry.status}</Text><Text className="mt-1 text-xs leading-4 text-[#B9D4C8]">{entry.detail} · {entry.tileCodes?.join(" · ") ?? entry.tileIds?.join(" · ") ?? "No tile selected"} · {formatActionLifecycleTime(entry.createdAt, language)}</Text></View></View>)}</View>{visibleActionTimeline.length === 0 ? <Text className="mt-2 text-xs text-[#B9D4C8]">No {actionFilter} actions in the current local timeline.</Text> : null}</ArenaCard> : null}

          <View className="rounded-2xl border border-[#2E6A59] bg-[#17493F] p-4"><View className="flex-row items-center justify-between"><Text className="text-sm font-bold text-[#F7F0E3]">Decision preview</Text><Text className="text-xs text-[#B9D4C8]">{legalityPreview.isFetching || scorePreview.isFetching ? "Refreshing…" : legalityPreview.error || scorePreview.error ? "Needs refresh" : "Backend synced"}</Text></View>{legalityPreview.error || scorePreview.error ? <View className="mt-3"><ArenaFeedback tone="warning" title="Preview is temporarily stale" message="The table remains playable, but the advisory signals could not be refreshed." /><Pressable onPress={() => { void legalityPreview.refetch(); void scorePreview.refetch(); }} accessibilityRole="button" style={({ pressed }) => ({ marginTop: 10, alignSelf: "flex-start", borderRadius: 10, backgroundColor: "#D7AA58", paddingHorizontal: 12, paddingVertical: 8, opacity: pressed ? 0.72 : 1 })}><Text className="text-xs font-bold text-[#17211F]">Refresh preview</Text></Pressable></View> : <View className="mt-3 flex-row gap-2"><View className="flex-1 rounded-xl bg-[#123C35] p-3"><Text className="text-[10px] uppercase text-[#B9D4C8]">Win paths</Text><Text className="mt-1 text-lg font-bold text-[#F7F0E3]">{Object.values(legalityPreview.data ?? {}).filter(Boolean).length}</Text></View><View className="flex-1 rounded-xl bg-[#123C35] p-3"><Text className="text-[10px] uppercase text-[#B9D4C8]">Preview points</Text><Text className="mt-1 text-lg font-bold text-[#F7F0E3]">{scorePreview.data?.points?.toLocaleString() ?? "—"}</Text></View></View>}<Text className="mt-2 text-xs leading-4 text-[#B9D4C8]">The preview is advisory: it reflects the current visible state and does not commit an action.</Text></View>

          <View className="rounded-2xl border border-[#2E6A59] bg-[#17493F] p-4">
            <View className="flex-row items-center justify-between"><Text className="text-sm font-bold text-[#F7F0E3]">Legal actions</Text><Text className="text-xs text-[#B9D4C8]">{legal.isFetching ? "Refreshing…" : `${enabledLegalActionCount} ready · ${legalActions.length} checked`}</Text></View>
            {legal.error ? <View><ArenaFeedback tone="error" title="Action state unavailable" message={explainGameplayError(legal.error.message)} /><Pressable onPress={() => void legal.refetch()} accessibilityRole="button" style={({ pressed }) => ({ marginTop: 10, alignSelf: "flex-start", borderRadius: 10, backgroundColor: "#F7F0E3", paddingHorizontal: 12, paddingVertical: 8, opacity: pressed ? 0.72 : 1 })}><Text className="text-xs font-bold text-[#17211F]">Retry legal actions</Text></Pressable></View> : <View className="mt-3 gap-2">{legalActions.filter((action) => action.type !== "discard").map((action) => <View key={action.type} className="flex-row items-center gap-2"><Pressable onPress={() => submitLegalAction(action)} disabled={!canSubmitLegalAction(action)} accessibilityRole="button" accessibilityLabel={`${action.label}${claimChoices(action).length ? `, ${claimChoices(action).length} tile combinations` : ""}${action.reason ? `: ${action.reason}` : ""}`} accessibilityHint={action.tileCodes?.length ? `Uses tile codes ${action.tileCodes.join(", ")}` : actionNeedsSelection(action) ? "Select the required tiles before submitting this action" : claimChoices(action).length > 1 ? "Opens a tile selection sheet" : undefined} accessibilityState={{ disabled: !canSubmitLegalAction(action) }} style={({ pressed }) => ({ flex: 1, minHeight: 48, borderRadius: 12, backgroundColor: canSubmitLegalAction(action) ? "#2E6A59" : "rgba(255,255,255,0.08)", paddingHorizontal: 14, paddingVertical: 11, justifyContent: "center", opacity: pressed ? 0.72 : 1, transform: [{ scale: pressed ? 0.98 : 1 }] })}><Text className="font-semibold text-[#F7F0E3]">{action.label}{claimChoices(action).length ? ` · ${claimChoices(action).length} combos` : ""}</Text></Pressable>{action.reason ? <Text className="flex-1 text-xs leading-4 text-[#B9D4C8]">{action.reason}</Text> : action.tileCodes?.length ? <View className="flex-1 flex-row flex-wrap items-center gap-1"><Text className="mr-1 text-[10px] uppercase tracking-wide text-[#D7AA58]">Tiles</Text>{action.tileCodes.slice(0, 4).map((code) => <View key={`${action.type}-${code}`} className="rounded-md border border-[#D7AA58] bg-[#123C35] px-2 py-1"><Text className="text-[10px] font-bold text-[#F7F0E3]">{code}</Text></View>)}</View> : actionNeedsSelection(action) ? <Text className="flex-1 text-xs leading-4 text-[#D7AA58]">{selectedTile ? "Choose one of the legal tiles for this action." : "Select the required tiles first."}</Text> : !action.enabled ? <Text className="flex-1 text-xs leading-4 text-[#D7AA58]">Unavailable for the current confirmed table state.</Text> : !isYourTurn ? <Text className="flex-1 text-xs leading-4 text-[#B9D4C8]">Waiting for Seat {state.currentSeat} to complete the turn.</Text> : null}</View>)}{legalActions.length === 0 ? <Text className="text-sm text-[#B9D4C8]">No special calls are available. Select a tile to discard when it is your turn.</Text> : <Text className="mt-1 text-xs leading-4 text-[#B9D4C8]">{availableActionSummary(legalActions)}</Text>}</View>}
          </View>
        </View>
      </ScrollView>

      {pendingDiscardAction ? <View className="absolute bottom-0 left-0 right-0 rounded-t-[28px] bg-[#F7F0E3] p-5 shadow-lg"><Text className="text-xs font-bold uppercase tracking-widest text-[#B87843]">Confirm discard</Text><Text className="mt-1 text-2xl font-bold text-[#17211F]">Review before sending</Text><Text className="mt-2 text-sm leading-5 text-[#7B6B5A]">You selected {selectedTileData?.code ?? "a tile"}. Confirm only if this is the discard you intend to send to the table.</Text><View className="mt-4 flex-row gap-2"><Pressable onPress={() => setPendingDiscardAction(null)} accessibilityRole="button" accessibilityLabel="Cancel discard confirmation" style={({ pressed }) => ({ flex: 1, borderRadius: 12, borderWidth: 1, borderColor: "#B87843", padding: 12, opacity: pressed ? 0.72 : 1 })}><Text className="text-center font-bold text-[#B87843]">Keep reviewing</Text></Pressable><Pressable onPress={() => pendingDiscardAction && selectedTile && submitLegalAction(pendingDiscardAction, [selectedTile])} disabled={!selectedTile || !canSubmitDiscard} accessibilityRole="button" accessibilityLabel={`Confirm discard ${selectedTileData?.code ?? "selected tile"}`} accessibilityHint="Submits this selected tile as the backend-approved discard" style={({ pressed }) => ({ flex: 1, borderRadius: 12, backgroundColor: "#D7AA58", padding: 12, opacity: !selectedTile || !canSubmitDiscard ? 0.45 : pressed ? 0.72 : 1 })}><Text className="text-center font-bold text-[#17211F]">Confirm discard</Text></Pressable></View></View> : null}

      {pendingClaim ? <View className="absolute bottom-0 left-0 right-0 rounded-t-[28px] bg-[#F7F0E3] p-5 shadow-lg"><Text className="text-xs font-bold uppercase tracking-widest text-[#B87843]">Action selection</Text><Text className="mt-1 text-2xl font-bold text-[#17211F]">{pendingClaim.label}</Text><Text className="mt-2 text-sm leading-5 text-[#7B6B5A]">Choose the exact tiles to use for this call. The selection is not submitted until you confirm. {pendingChoices.length} legal combination{pendingChoices.length === 1 ? "" : "s"} found.</Text><Text className="mt-2 rounded-xl bg-[#FFF0D5] p-3 text-xs leading-4 text-[#8B5A2B]">This chooser stays open only while the confirmed table state is unchanged. If another seat acts first, the selection will be cleared safely.</Text><View className="mt-4 gap-2">{pendingChoices.map((choice, index) => { const ids = choice.map((tile) => tile.id); const selected = ids.join(",") === selectedClaimTiles.join(","); return <Pressable key={`${pendingClaim.type}-${index}`} onPress={() => setSelectedClaimTiles(ids)} accessibilityRole="button" accessibilityState={{ selected }} style={({ pressed }) => ({ borderRadius: 12, borderWidth: 1, borderColor: selected ? "#B87843" : "#D7C8B2", backgroundColor: selected ? "#FFF0D5" : "#FFF8EC", padding: 12, opacity: pressed ? 0.72 : 1 })}><Text className="font-bold text-[#17211F]">{choice.map((tile) => tile.code).join(" · ")}</Text><Text className="mt-1 text-xs text-[#7B6B5A]">{selected ? `Selected combination ${index + 1} of ${pendingChoices.length}` : `Tap to select combination ${index + 1} of ${pendingChoices.length}`}</Text></Pressable>; })}</View><View className="mt-4 flex-row gap-2"><Pressable onPress={() => { setPendingClaim(null); setSelectedClaimTiles([]); }} accessibilityRole="button" style={({ pressed }) => ({ flex: 1, borderRadius: 12, borderWidth: 1, borderColor: "#B87843", padding: 12, opacity: pressed ? 0.72 : 1 })}><Text className="text-center font-bold text-[#B87843]">Cancel</Text></Pressable><Pressable onPress={() => pendingClaim && submitLegalAction(pendingClaim, selectedClaimTiles)} disabled={!selectedClaimTiles.length || !canAct} accessibilityRole="button" accessibilityLabel={`Confirm ${pendingClaim?.label ?? "claim"}${selectedClaimTiles.length ? ` with ${selectedClaimTiles.length} selected tiles` : ""}`} accessibilityHint="Submits the selected meld only if the confirmed table state is still current" style={({ pressed }) => ({ flex: 1, borderRadius: 12, backgroundColor: "#D7AA58", padding: 12, opacity: !selectedClaimTiles.length || !canAct ? 0.45 : pressed ? 0.72 : 1 })}><Text className="text-center font-bold text-[#17211F]">{submit.isPending ? "Submitting…" : selectedClaimTiles.length ? `Confirm ${selectedClaimTiles.length} tile${selectedClaimTiles.length === 1 ? "" : "s"}` : "Select tiles"}</Text></Pressable></View></View> : null}

      {showCopilot ? <View className="absolute bottom-0 left-0 right-0 rounded-t-[28px] bg-[#F7F0E3] p-5 shadow-lg">
        <View className="mb-4 flex-row items-center justify-between"><View><Text className="text-xs font-bold uppercase tracking-widest text-[#B87843]">AI Copilot · {coachingModeLabel(coachingMode)}</Text><Text className="mt-1 text-2xl font-bold text-[#17211F]">Decision snapshot</Text><Text className="mt-1 text-xs leading-4 text-[#7B6B5A]">{coachingModeDescription(coachingMode)}</Text></View><Pressable onPress={() => setShowCopilot(false)}><Text className="text-2xl text-[#7B6B5A]">×</Text></Pressable></View>
        {analysis.isPending ? <ArenaSkeleton lines={3} /> : analysis.error ? <View><ArenaFeedback tone="error" title="Copilot needs a fresh state" message={analysis.error.message} /><Pressable onPress={() => { analysis.reset(); modeComparison.reset(); analysis.mutate({ id: String(id), seat: 0, policy: "balanced", useLLM: false, coachingMode }); modeComparison.mutate({ id: String(id), seat: 0 }); }} accessibilityRole="button" style={({ pressed }) => ({ marginTop: 12, borderRadius: 12, backgroundColor: "#D7AA58", padding: 12, opacity: pressed ? 0.72 : 1 })}><Text className="text-center font-bold text-[#17211F]">Retry Copilot</Text></Pressable></View> : recommended ? <View className="gap-3"><Text className="text-xs font-bold uppercase tracking-wide text-[#B87843]">{selectedTileData ? `Comparing selected ${selectedTileData.code}` : "Comparing the current hand"}</Text><Text className="text-base leading-6 text-[#17211F]">The {coachingModeLabel(selectedComparisonMode ?? coachingMode).toLowerCase()} coaching mode prefers {recommended.action.tileCodes?.[0] ?? "this discard"}. {recommended.rationale}</Text>{analysis.data?.recommendationSummary ? <View className="rounded-xl border border-[#E7D5B8] bg-[#FFF8EC] p-3"><Text className="text-xs font-bold uppercase tracking-widest text-[#8B5A2B]">Why this line leads</Text><Text className="mt-2 text-sm leading-5 text-[#17211F]">{analysis.data.recommendationSummary.keyTradeoff}</Text><Text className="mt-2 text-xs leading-4 text-[#7B6B5A]">Runner-up: {analysis.data.recommendationSummary.runnerUpTile ?? "not available"} · confidence gap {Math.round(analysis.data.recommendationSummary.confidenceGap * 100)}% · ukeire change {analysis.data.recommendationSummary.ukeireDelta >= 0 ? "+" : ""}{analysis.data.recommendationSummary.ukeireDelta}</Text><Text className="mt-2 text-xs font-bold uppercase tracking-wide text-[#8B5A2B]">{analysis.data.recommendationSummary.confidenceBand ?? "calibrating"} confidence · {Math.round((analysis.data.recommendationSummary.evidenceQuality ?? 0) * 100)}% evidence · focus {analysis.data.recommendationSummary.learningFocus ?? "speed"}</Text><Text className="mt-1 text-xs leading-4 text-[#7B6B5A]">{analysis.data.recommendationSummary.confidenceBasis ?? "Sensei is comparing the leading lines from the visible state."}</Text><Text className="mt-2 text-sm leading-5 text-[#17211F]">{analysis.data.recommendationSummary.counterfactualLesson ?? "Compare the runner-up line before committing."}</Text><Text className="mt-1 text-xs leading-4 text-[#7B6B5A]">{analysis.data.recommendationSummary.riskNote ?? "Check visible danger signals before pushing."} Utility separation: {analysis.data.recommendationSummary.utilityDelta ?? 0}.</Text></View> : null}<View className="flex-row gap-2"><ArenaMetric label="Shanten after" value={recommended.shantenAfter} progress={1 - Math.min(1, recommended.shantenAfter / 6)} /><ArenaMetric label="Ukeire" value={recommended.ukeire} progress={Math.min(1, recommended.ukeire / 20)} /><ArenaMetric label="Confidence" value={Math.round(recommended.confidence * 100)} suffix="%" progress={recommended.confidence} /></View><Text className="text-xs leading-5 text-[#7B6B5A]">{analysis.data?.disclaimer}</Text>{modeComparison.isPending ? <Text className="text-xs text-[#8B5A2B]">Comparing all coaching modes…</Text> : modeComparison.error ? <View className="rounded-xl border border-[#E4B4A8] bg-[#FDE9E4] p-3"><Text className="text-xs font-bold text-[#8E3D2E]">Mode comparison is temporarily unavailable.</Text><Text className="mt-1 text-[10px] leading-4 text-[#8E3D2E]">The primary recommendation is still usable. Retry when the table state is stable.</Text><Pressable onPress={() => { modeComparison.reset(); modeComparison.mutate({ id: String(id), seat: 0 }); }} accessibilityRole="button" style={({ pressed }) => ({ marginTop: 8, alignSelf: "flex-start", borderRadius: 8, backgroundColor: "#D7AA58", paddingHorizontal: 10, paddingVertical: 7, opacity: pressed ? 0.72 : 1 })}><Text className="text-[10px] font-bold text-[#17211F]">Retry comparison</Text></Pressable></View> : modeComparison.data?.length ? <View className="rounded-xl border border-[#D7C8B2] bg-[#FFF8EC] p-3"><Text className="text-xs font-bold uppercase tracking-wide text-[#8B5A2B]">Same hand · three risk budgets</Text><Text className="mt-1 text-[10px] leading-4 text-[#7B6B5A]">Tap a card to make its line active. Sensei will frame the next action around that risk budget.</Text><View className="mt-2 gap-2">{modeComparison.data.map((candidate) => <Pressable key={candidate.recommendationId} onPress={() => setSelectedComparisonMode(candidate.recommendationId.endsWith("-defensive") ? "defensive" : candidate.recommendationId.endsWith("-exploratory") ? "exploratory" : "balanced")} accessibilityRole="button" accessibilityState={{ selected: (selectedComparisonMode ?? coachingMode) === (candidate.recommendationId.endsWith("-defensive") ? "defensive" : candidate.recommendationId.endsWith("-exploratory") ? "exploratory" : "balanced") }} style={({ pressed }) => ({ borderRadius: 8, borderWidth: 1, borderColor: (selectedComparisonMode ?? coachingMode) === (candidate.recommendationId.endsWith("-defensive") ? "defensive" : candidate.recommendationId.endsWith("-exploratory") ? "exploratory" : "balanced") ? "#B87843" : "#E7D5B8", backgroundColor: (selectedComparisonMode ?? coachingMode) === (candidate.recommendationId.endsWith("-defensive") ? "defensive" : candidate.recommendationId.endsWith("-exploratory") ? "exploratory" : "balanced") ? "#FFF0D5" : "white", padding: 8, opacity: pressed ? 0.72 : 1 })}><View className="flex-row items-center justify-between"><Text className="text-xs font-bold text-[#17211F]">{candidate.recommendationId.endsWith("-defensive") ? "Defensive" : candidate.recommendationId.endsWith("-exploratory") ? "Exploratory" : "Balanced"}</Text><Text className="text-[10px] font-bold text-[#8B5A2B]">{candidate.alternatives[0]?.action.tileCodes?.[0] ?? "—"} · {Math.round((candidate.alternatives[0]?.confidence ?? 0) * 100)}%</Text></View><Text className="mt-1 text-[10px] leading-4 text-[#7B6B5A]">{candidate.alternatives[0]?.rationale ?? "No line available."}</Text></Pressable>)}</View><Text className="mt-2 text-[10px] font-bold uppercase tracking-wide text-[#8B5A2B]">Active line · {coachingModeLabel(selectedComparisonMode ?? coachingMode)}</Text></View> : null}</View> : <ArenaFeedback tone="warning" title="No recommendation yet" message="Ask Copilot again after the live state refreshes so it can compare the current legal lines." />}
      </View> : null}
    </ScreenContainer>
  );
}
